<script setup lang="ts">
import { ref } from 'vue';import { useRouter } from 'vue-router';import { login,prepare,run,state,uploadPendingAutomatically } from '../store';
const email=ref(''),password=ref(''),visible=ref(false),busy=ref(false),router=useRouter();
async function submit(){busy.value=true;await run(async()=>{try{await login(email.value,password.value);await router.replace('/');await uploadPendingAutomatically();if(state.auth)await prepare()}finally{password.value=''}});busy.value=false}
</script>
<template><section class="login-page"><div class="login-heading"><span class="eyebrow">أهلًا بك في حلقة</span><h1>متابعة أقرب،<br>لكل طالب.</h1><p>سجّل الدخول بحساب الأستاذ الذي أنشأته الإدارة.</p></div><form class="card form" @submit.prevent="submit"><h2>تسجيل الدخول</h2><label>البريد الإلكتروني<input v-model="email" type="email" dir="ltr" autocomplete="username" required></label><label>كلمة المرور<span class="password-field"><input v-model="password" :type="visible?'text':'password'" autocomplete="current-password" required><button type="button" :aria-pressed="visible" :aria-label="visible?'إخفاء كلمة المرور':'إظهار كلمة المرور'" @click="visible=!visible">{{visible?'إخفاء':'إظهار'}}</button></span></label><button class="primary" :disabled="busy||!state.online">{{busy?'جارٍ الدخول…':'تسجيل الدخول'}}</button><p v-if="!state.online" class="muted">تسجيل الدخول يحتاج اتصالًا بالإنترنت. لا يمكن تحميل بيانات الحصص دون اتصال.</p></form></section></template>
